# Databricks notebook source
import base64
import gzip
import hashlib
import io
import tarfile

dbutils.widgets.text("run_id", "")
dbutils.widgets.text("run_open_ts", "")
dbutils.widgets.text("silver_update_id", "")
RUN = dbutils.widgets.get("run_id").strip()
RUN_OPEN_TS = dbutils.widgets.get("run_open_ts").strip()
SILVER_UPDATE_ID = dbutils.widgets.get("silver_update_id").strip()
assert RUN.startswith("dq4_silver_") and RUN.replace("_", "").isalnum(), RUN
assert RUN_OPEN_TS and SILVER_UPDATE_ID
LANE = "dq4_results"
PAYLOAD = """"""

def qs(value):
    if value is None:
        return "NULL"
    return "'" + str(value).replace("'", "''") + "'"

def adapt(value):
    return (value
        .replace("dq4_silver_20260825", RUN)
        .replace("2026-08-25T10:50:49.897Z", RUN_OPEN_TS)
        .replace("f5c7c7ab-e37d-4a31-b9c2-b7631becb16a", SILVER_UPDATE_ID))

def unpack():
    archive = tarfile.open(fileobj=io.BytesIO(base64.b64decode(PAYLOAD)), mode="r:gz")
    items = []
    for member in archive.getmembers():
        if member.isfile() and member.name.endswith(".sql"):
            items.append((member.name, adapt(archive.extractfile(member).read().decode("utf-8"))))
    return sorted(items, key=lambda x: x[0])

def execute(seq, name, sql):
    sha = hashlib.sha256(sql.encode()).hexdigest()
    spark.sql(f"""INSERT INTO 6_mgmt.silver_qc.dq_exec_log
      (run_id,lane,stmt_file,seq,stmt_sha256,status,error_text,rows_affected,attempted_at,settled_at,created_by_session)
      VALUES ({qs(RUN)},{qs(LANE)},{qs(name)},{seq},{qs(sha)},'attempted',NULL,NULL,current_timestamp(),NULL,'DQ4')""")
    try:
        spark.sql(sql).collect()
        spark.sql(f"""INSERT INTO 6_mgmt.silver_qc.dq_exec_log
          (run_id,lane,stmt_file,seq,stmt_sha256,status,error_text,rows_affected,attempted_at,settled_at,created_by_session)
          VALUES ({qs(RUN)},{qs(LANE)},{qs(name)},{seq},{qs(sha)},'ok',NULL,NULL,current_timestamp(),current_timestamp(),'DQ4')""")
    except Exception as exc:
        msg = str(exc)[:4000]
        spark.sql(f"""INSERT INTO 6_mgmt.silver_qc.dq_exec_log
          (run_id,lane,stmt_file,seq,stmt_sha256,status,error_text,rows_affected,attempted_at,settled_at,created_by_session)
          VALUES ({qs(RUN)},{qs(LANE)},{qs(name)},{seq},{qs(sha)},'error',{qs(msg)},NULL,current_timestamp(),current_timestamp(),'DQ4')""")
        raise

run_row = spark.sql(f"SELECT count(*) n FROM 6_mgmt.silver_qc.dq_run WHERE run_id={qs(RUN)} AND finished_at IS NULL").first().n
assert run_row == 1, "run_id must identify one open dq_run row"

existing = spark.sql(f"SELECT count(*) n FROM 6_mgmt.silver_qc.dq_check_result WHERE run_id={qs(RUN)} AND created_by_session='DQ4'").first().n
assert existing == 15, f"expected 15 singles results before derived results, found {existing}"

items = unpack()

# The frozen DQ4 spec built the coded-product trend scratch tables in a manual
# dq4_trend lane that never made it into this notebook; build them here (DQ4 plan
# Task 4 Step 4: 39-month window ending at the first day of the run month) and
# re-pin the frozen 2026-08-01 window end to the run month.
import datetime
import re
WINDOW_END = datetime.date.fromisoformat(RUN_OPEN_TS[:10]).replace(day=1)
_m = WINDOW_END.year * 12 + WINDOW_END.month - 1 - 39
WINDOW_START = datetime.date(_m // 12, _m % 12 + 1, 1)
items = [(name, sql.replace("'2026-08-01'", f"'{WINDOW_END}'")) for name, sql in items]
trend_products = sorted({p for _, sql in items for p in re.findall(r"dq4_trend_(\w+?)_" + RUN + r"\b", sql)})
for i, prod in enumerate(trend_products):
    execute(1000 + i, f"trend_{prod}.sql", f"""CREATE OR REPLACE TABLE `6_mgmt`.silver_qc_tmp.dq4_trend_{prod}_{RUN} AS
SELECT coalesce(source_code, '__none__') AS code,
       CAST(date_trunc('month', event_datetime) AS DATE) AS month,
       count(*) AS n
FROM 4_prod.silver.{prod}
WHERE event_datetime >= CAST('{WINDOW_START}' AS TIMESTAMP)
  AND event_datetime <  CAST('{WINDOW_END}' AS TIMESTAMP)
GROUP BY 1, 2""")

for seq, (name, sql) in enumerate(items):
    execute(seq, name, sql)

total = spark.sql(f"SELECT count(*) n, count(DISTINCT check_id) d FROM 6_mgmt.silver_qc.dq_check_result WHERE run_id={qs(RUN)} AND created_by_session='DQ4'").first()
assert total.n == total.d, total

print({"run_id": RUN, "lane": LANE, "statements": len(items), "status": "ok"})

